<script lang="ts">
 import {onMount} from 'svelte';import {api,type StorageStatus} from '#lib/api.ts';import {t} from '#lib/i18n/index.svelte.ts';import PageHead from '#lib/components/PageHead.svelte';import HistoryChart from '#lib/operations/HistoryChart.svelte';import {operationError,type MonitorSettings,type MonitorStatus,type MonitorSample} from '#lib/operations.ts';
 let status=$state<MonitorStatus|null>(null),settings=$state<MonitorSettings|null>(null),storage=$state<StorageStatus|null>(null),samples=$state<MonitorSample[]>([]),hours=$state(24),busy=$state(false),error=$state(''),saved=$state(false),disk=$state(''),network=$state('');
 const disks=$derived([...new Set(samples.flatMap(s=>s.disks.map(d=>d.name)))].sort()),networks=$derived([...new Set(samples.flatMap(s=>s.networks.map(n=>n.name)))].sort());
 async function load(){busy=true;error='';try{status=await api.get('/monitoring');if(!settings)settings=structuredClone($state.snapshot(status!.settings));samples=await api.get(`/monitoring/history?hours=${hours}`);if(!disks.includes(disk))disk=disks[0]??'';if(!networks.includes(network))network=networks[0]??'';}catch(e){error=operationError(e,t);}finally{busy=false;}}
 onMount(()=>{load();api.get<StorageStatus>('/storage').then(s=>storage=s).catch(e=>error=operationError(e,t));});
 async function save(){if(!settings)return;busy=true;saved=false;error='';try{status=await api.put('/monitoring',settings);settings=structuredClone($state.snapshot(status!.settings));saved=true;}catch(e){error=operationError(e,t);}finally{busy=false;}if(!error)load();}
</script>
<PageHead title={t('ops.monitoring')} parent={{href:'/tools',label:t('nav.tools')}}>{#snippet actions()}<button class="btn" disabled={busy} onclick={load}>{t('ops.refresh')}</button>{/snippet}</PageHead>
<p class="muted">{t('ops.monitorHint')}</p>{#if error}<p class="notice-error" role="alert">{error}</p>{/if}{#if status?.error}<p class="notice-warn">{status.error}</p>{/if}
{#if settings}<form class="tile settings" onsubmit={e=>{e.preventDefault();save();}}><label class="check"><input type="checkbox" bind:checked={settings.enabled}/>{t('ops.enabled')}</label><label>{t('ops.volume')}<select class="field" bind:value={settings.volume} required={settings.enabled}><option value="">{t('ops.choose')}</option>{#each storage?.volumes??[] as volume(volume.name)}<option value={volume.name}>{volume.name}</option>{/each}</select></label><label>{t('ops.days')}<select class="field" bind:value={settings.days}><option value={7}>7</option><option value={30}>30</option></select></label><label>{t('ops.budget')}<input class="field" type="number" min="8" max="256" bind:value={settings.maxMiB} required/></label><button class="btn btn-primary" disabled={busy}>{t('ops.save')}</button>{#if saved}<span role="status">{t('notify.saved')}</span>{/if}</form>{/if}
<div class="toolbar"><label>{t('ops.range')}<select class="field" bind:value={hours} disabled={busy} onchange={load}><option value={24}>24 h</option><option value={168}>7 d</option><option value={720}>30 d</option></select></label><span class="muted">{t('ops.samples',{count:samples.length})}</span></div>
<div class="charts"><HistoryChart {samples} value={s=>s.cpu} label={t('ops.cpu')} maximum={100}/><HistoryChart {samples} value={s=>s.ramTotal?100*(s.ramTotal-s.ramAvailable)/s.ramTotal:null} label={t('ops.ram')} maximum={100}/></div>
<div class="toolbar"><label>{t('ops.io')}<select class="field" bind:value={disk}>{#each disks as name(name)}<option value={name}>{name}</option>{/each}</select></label></div>
<div class="charts"><HistoryChart {samples} value={s=>{const d=s.disks.find(d=>d.name===disk);return d?d.readBps/1048576:null;}} label={t('ops.read')} unit="MiB/s"/><HistoryChart {samples} value={s=>{const d=s.disks.find(d=>d.name===disk);return d?d.writeBps/1048576:null;}} label={t('ops.write')} unit="MiB/s"/><HistoryChart {samples} value={s=>s.disks.find(d=>d.name===disk)?.latencyMs??null} label={t('ops.latency')} unit="ms"/></div>
<div class="toolbar"><label>{t('ops.network')}<select class="field" bind:value={network}>{#each networks as name(name)}<option value={name}>{name}</option>{/each}</select></label></div>
<div class="charts"><HistoryChart {samples} value={s=>{const n=s.networks.find(n=>n.name===network);return n?n.receive/1048576:null;}} label={t('ops.receive')} unit="MiB/s"/><HistoryChart {samples} value={s=>{const n=s.networks.find(n=>n.name===network);return n?n.send/1048576:null;}} label={t('ops.send')} unit="MiB/s"/>
 {#each [...new Set(samples.flatMap(s=>s.volumes.map(v=>v.name)))].sort() as name(name)}<HistoryChart {samples} value={s=>{const v=s.volumes.find(v=>v.name===name);return v?v.used/1073741824:null;}} label={`${t('ops.usage')} · ${name}`} unit="GiB"/>{/each}</div>
<style>.settings{display:flex;flex-wrap:wrap;align-items:end;gap:14px;padding:var(--tile-pad)}label{display:flex;flex-direction:column;gap:6px;min-width:0;font-size:.85rem}.settings label{flex:1 1 150px}.check{flex-direction:row;align-items:center}.toolbar{display:flex;align-items:end;flex-wrap:wrap;gap:16px;margin:20px 0 12px}.toolbar select{width:auto;min-width:130px}.charts{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,330px),1fr));gap:var(--gap)}</style>
